UPDATE daily_reports
SET content = '{"overview":{"tone":"mixed","interpretation":"道指和标普上涨对美国大盘估值形成支撑，但纳斯达克下跌且美国长端利率上行，抬高无风险利率并压制成长估值；中国主要指数同步下跌，削弱风险偏好与权益融资环境。","positive":["美国大盘价值股","标普大盘股"],"negative":["美国成长股","中国大盘股"]},"marketViews":{"CN":{"headline":"中国主要指数同步回落","summary":"上证指数与沪深大盘指数同步下跌，中国权益市场风险偏好明显承压。","overview":{"tone":"negative","interpretation":"两项主要指数同步下跌，对大盘股估值和市场风险偏好构成利空，并可能压制权益融资环境；指数覆盖的广泛权重板块共同承压。","positive":[],"negative":["中国大盘股","指数权重板块"]}},"US":{"headline":"美国股指分化利率上行","summary":"道指和标普上涨，纳斯达克下跌，同时长端利率走高。","overview":{"tone":"mixed","interpretation":"道指和标普上涨，为大盘价值估值与风险偏好提供支撑；纳斯达克下跌叠加长端利率上行，抬高无风险利率并压制久期较长的成长资产估值。","positive":["美国大盘价值股","标普大盘股"],"negative":["美国成长股","长久期资产"]}}},"markets":[{"region":"US","name":"S&P 500","symbol":"SPX","value":"7,411.98","change":"+0.05%","direction":"up","note":"FRED 日收盘","source":"https://fred.stlouisfed.org/series/SP500"},{"region":"US","name":"NASDAQ","symbol":"IXIC","value":"24,975.82","change":"-0.64%","direction":"down","note":"FRED 日收盘","source":"https://fred.stlouisfed.org/series/NASDAQCOM"},{"region":"US","name":"DOW","symbol":"DJI","value":"51,947.25","change":"+0.46%","direction":"up","note":"FRED 日收盘","source":"https://fred.stlouisfed.org/series/DJIA"},{"region":"US","name":"美国 10Y","symbol":"DGS10","value":"4.71%","change":"+4 bp","direction":"up","note":"FRED 日收盘 · 07-23","source":"https://fred.stlouisfed.org/series/DGS10"},{"region":"CN","name":"上证指数","symbol":"SSE","value":"3,814.20","change":"-1.61%","direction":"down","note":"腾讯证券日收盘","source":"https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param=sh000001%2Cday%2C2026-07-06%2C2026-07-26%2C40%2Cqfq"},{"region":"CN","name":"沪深 300","symbol":"CSI300","value":"4,649.19","change":"-1.67%","direction":"down","note":"腾讯证券日收盘","source":"https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param=sh000300%2Cday%2C2026-07-06%2C2026-07-26%2C40%2Cqfq"}],"sectorHeat":[{"market":"CN","symbol":"932078","name":"原材料","nameEn":"Materials","score":77,"change":"-3.86%","direction":"down","asOf":"2026-07-24","source":"https://www.csindex.com.cn/#/indices/family/detail?indexCode=932078"},{"market":"CN","symbol":"932086","name":"公用事业","nameEn":"Utilities","score":75,"change":"-3.77%","direction":"down","asOf":"2026-07-24","source":"https://www.csindex.com.cn/#/indices/family/detail?indexCode=932086"},{"market":"CN","symbol":"932082","name":"医药卫生","nameEn":"Health Care","score":72,"change":"-3.60%","direction":"down","asOf":"2026-07-24","source":"https://www.csindex.com.cn/#/indices/family/detail?indexCode=932082"},{"market":"US","symbol":"XLRE","name":"房地产","nameEn":"Real Estate","score":74,"change":"+2.22%","direction":"up","asOf":"2026-07-24","source":"https://www.nasdaq.com/market-activity/etf/xlre/historical"},{"market":"US","symbol":"XLB","name":"原材料","nameEn":"Materials","score":64,"change":"+1.93%","direction":"up","asOf":"2026-07-24","source":"https://www.nasdaq.com/market-activity/etf/xlb/historical"},{"market":"US","symbol":"XLK","name":"信息技术","nameEn":"Information Technology","score":48,"change":"-1.44%","direction":"down","asOf":"2026-07-24","source":"https://www.nasdaq.com/market-activity/etf/xlk/historical"}],"stories":[{"id":"1aa2710a75acf197","regions":["CN"],"category":"宏观","importance":4,"title":"服务与通讯消费快于商品零售","summary":"上半年服务零售增速快于商品消费，通讯器材零售增长较快，社会消费品零售总额温和增长。","evidence":"原始标题：商务部消费促进司负责人谈2026年上半年我国消费市场情况；核验事实：上半年商品和服务零售额同比增长2.7%，服务零售额增长5.3%，社会消费品零售总额增长1.3%；通讯器材类零售额增长14.4%，服务消费快于商品消费。","source":"https://www.mofcom.gov.cn/xwfb/sjfzrfb/art/2026/art_94370a437fc4484ab1b01c5236d12dec.html","sourceLabel":"商务部","publishedAt":"2026-07-24T00:42:00.000Z","ai":{"tone":"mixed","interpretation":"服务和通讯器材消费较快增长，利好相关企业收入与现金流；社会消费品零售总额增速较低，显示商品需求支撑偏弱并压制传统零售，消费板块内部影响分化。","sectors":["服务消费","通讯器材","零售"],"tickers":[]}},{"id":"f063f19ff7c2afc7","regions":["CN"],"category":"商品","importance":4,"title":"生产资料价格上下游影响分化","summary":"重要生产资料价格涨多跌少，铜铝及多种化工品上涨，磷酸铁锂价格明显下降。","evidence":"原始标题：2026年7月中旬流通领域重要生产资料市场价格变动情况；核验事实：国家统计局监测的50种重要生产资料中，26种价格上涨、19种下降、5种持平；铜、铝及多种化工品上涨，而磷酸铁锂下跌4.6%，上下游成本影响明显分化。","source":"https://www.stats.gov.cn/sj/zxfb/202607/t20260723_1964185.html","sourceLabel":"国家统计局","publishedAt":"2026-07-24T01:30:00.000Z","ai":{"tone":"mixed","interpretation":"铜铝和化工品涨价提高上游销售价格与收入预期，但增加下游采购成本；磷酸铁锂降价则压低材料企业收入、降低电池制造成本，产业链利润传导明显分化。","sectors":["有色金属","化工","电池材料"],"tickers":[]}},{"id":"b091d83c6a8cc853","regions":["US"],"category":"宏观","importance":3,"title":"美股指数周五分化且全周收跌","summary":"标普与道指周五上涨、纳指下跌，三大指数全周均收低，油价在此前上涨一周后回落。","evidence":"原始标题：How major US stock indexes fared Friday 7/24/2026；核验事实：The S&P 500 rose less than 0.1% and the Dow Jones Industrial Average gained 0.5%, while the Nasdaq composite fell 0.6%. All three indexes finished the week lower, and oil prices fell after a week of gains.","source":"https://apnews.com/article/02d01b8f38ccd51f605c4414cdd4fa9b","sourceLabel":"Associated Press","publishedAt":"2026-07-24T20:16:00.000Z","ai":{"tone":"mixed","interpretation":"标普与道指上涨支撑大盘权重和当日风险偏好，但纳指下跌及全周收低压制成长估值；油价回落降低能源企业收入预期，同时缓解交通与消费行业成本。","sectors":["美国股市","成长股","能源"],"tickers":[]}},{"id":"8c1f0d571f61b6f8","regions":["CN"],"category":"行业","importance":4,"title":"苏州电子信息与工业产出提速","summary":"苏州工业产出保持增长，电子信息、工业机器人和集成电路产量表现较强。","evidence":"原始标题：上半年苏州规模以上工业总产值突破25000亿元；核验事实：上半年苏州规模以上工业总产值25017.6亿元、同比增长6.9%，规模以上工业增加值增长9.3%；电子信息业产值增长10.0%，工业机器人和集成电路产量分别增长41.3%和15.3%。","source":"https://wallstreetcn.com/livenews/3139741","sourceLabel":"华尔街见闻（引苏州市统计局）","publishedAt":"2026-07-25T11:15:02.000Z","ai":{"tone":"positive","interpretation":"电子信息产出和机器人产量增长利好长三角设备与芯片订单，并通过工业需求改善支撑制造业现金流。","sectors":["电子信息","工业机器人","半导体"],"tickers":[]}},{"id":"a82fb3de4a112e9d","regions":["US"],"category":"宏观","importance":5,"title":"美债收益率全周明显上行","summary":"美国两年期和十年期国债收益率全周上升，实际利率也同步走高。","evidence":"原始标题：美国两年期国债收益率本周涨15.6个基点；核验事实：截至7月24日当周，美国10年期国债收益率累计上涨12.96个基点至4.6771%，两年期收益率累计上涨15.60个基点至4.3306%，10年期通胀保值国债收益率累计上涨13.78个基点至2.4291%。","source":"https://wallstreetcn.com/livenews/3139665","sourceLabel":"华尔街见闻","publishedAt":"2026-07-24T21:33:18.000Z","ai":{"tone":"negative","interpretation":"名义与实际收益率上行抬高无风险利率和折现率，利空高估值成长股与利率敏感资产。","sectors":["成长股","房地产","公用事业"],"tickers":[]}},{"id":"2c242017eb037b99","regions":["US"],"category":"行业","importance":3,"title":"美国证监会研究全天候股票交易","summary":"美国证监会将讨论全天候股票交易所需的隔夜运营、市场韧性和投资者保护。","evidence":"原始标题：SEC Announces Roundtable on Preparations for 24-Hour Trading；核验事实：The SEC announced a September 17 roundtable on preparations for 24-hour U.S. equity trading, including overnight operations, market resiliency, investor protection and the infrastructure needed to support extended access.","source":"https://www.sec.gov/newsroom/press-releases/2026-69-sec-announces-roundtable-preparations-24-hour-trading","sourceLabel":"U.S. Securities and Exchange Commission","publishedAt":"2026-07-23T15:04:00.000Z","ai":{"tone":"mixed","interpretation":"更长交易时段利好交易所与券商交易收入，但隔夜流动性和系统投入会增加运营成本与价格波动风险。","sectors":["交易所","券商","金融科技"],"tickers":[]}},{"id":"98dc7e088515af8b","regions":["CN"],"category":"行业","importance":4,"title":"中基协澄清量化集中砸盘说法","summary":"中基协私募专业委员会称，多家量化机构在市场下跌日为净买入，并无集中砸盘。","evidence":"原始标题：科技股大跌是因为“量化砸盘”？中基协私募专业委员会详解A股量化交易；核验事实：近日，中国证券投资基金业协会私募证券投资基金专业委员会表示，“经向头部券商和量化私募机构了解，在上周市场下跌幅度较大的交易日，很多量化机构不仅没有净卖出，还是净买入，而且有的机构净买入金额还较大，没有‘集中砸盘’。”从指数增强、量化多头、量化中性等主流量化产品的运行模式看，一般都是满仓或接近满仓操作，买卖交易是在不同股票间调整。短时间内“集中砸盘”不仅不会增加其收益，反而会导致损失，所以量化机构本身也没有主动“集中砸盘”的意愿。（第一财经）","source":"https://wallstreetcn.com/livenews/3139765","sourceLabel":"华尔街见闻","publishedAt":"2026-07-25T13:51:03.000Z","ai":{"tone":"positive","interpretation":"净买入事实缓解对量化交易机制的担忧，利好A股风险偏好与券商交易生态，但不直接改变企业盈利。","sectors":["量化交易","券商","A股"],"tickers":[]}},{"id":"02945394ec0702ba","regions":["CN"],"category":"行业","importance":4,"title":"国产超大型液化天然气船交付","summary":"我国自主设计建造的第二艘十八万立方米超大型液化天然气运输船完成交付。","evidence":"原始标题：第二艘国产18万方超大型LNG运输船今天交付；核验事实：【第二艘国产18万方超大型LNG运输船今天交付】财联社7月25日电，在江苏南通招商重工码头，我国自主设计建造的第二艘18万立方米超大型LNG运输船“果阿”轮顺利交付。LNG运输船是专门用于运输零下163℃低温液化天然气的特种船舶，因设计与建造工艺难度极高，被誉为“造船业皇冠上的明珠”。本次交付的“果阿”轮总长298.8米，型宽48米，兼具低蒸发损耗、绿色低碳、节能环保等突出性能，技术指标达到国际先进水平。据统计，2026年以来南通地区已有50多艘新造船舶完成出口交付。","source":"https://www.cls.cn/detail/2437034","sourceLabel":"财联社","publishedAt":"2026-07-25T13:33:30.000Z","ai":{"tone":"positive","interpretation":"高技术船舶交付验证建造能力并兑现订单收入，利好船舶制造、低温装备和出口供应链现金流。","sectors":["船舶制造","低温装备","出口链"],"tickers":[]}},{"id":"58f803d6b80151d2","regions":["US"],"category":"行业","importance":4,"title":"美股存储芯片链周五大幅回撤","summary":"美国存储芯片与硬件供应链指数周五明显下跌，但全周仍保留涨幅。","evidence":"原始标题：美股存储芯片指数收跌约7.3%，使得本周累计涨幅收窄至不足6%；核验事实：周五（7月24日），美股存储芯片与硬件供应链指数跌7.29%，报200.25点，本周累计上涨5.74%，整体处于上涨状态，7月23-24日持续回撤。 美国科技股七巨头（Magnificent 7）指数涨0.42%，报209.53点，本周累跌3.45%，7月20-22日大致持平，7月23日跳空低开、之后低位持稳。 “超大”市值科技股指数跌0.69%，报414.60点，本周累跌3.75%。 美股超大规模云服务商（Hyperscalers）跌0.74%，报85.78点，本周累跌6.75%。 信息科技指数跌3.54%，报384.43点，本周累涨2.67%。 周五当天，成分股Nebius Group NV收跌15.02%，CoreWeave跌11.37%，Astera Labs跌10.82%，闪迪跌10.79%，Credo科技集团控股跌9.87%，高意公司/相干公司Coherent跌9.84%跌幅第六大，Adobe则涨6.10%表现第二，ServiceNOW涨7.44%。 人工智能（AI）赢家指数跌4.77%，报379.02点，本周累涨0.81%。 AI软件先驱指数涨1.62%，报103.70点，本周累跌4.46%。","source":"https://wallstreetcn.com/livenews/3139661","sourceLabel":"华尔街见闻","publishedAt":"2026-07-24T21:20:24.000Z","ai":{"tone":"negative","interpretation":"单日大幅回撤压制存储芯片和人工智能硬件风险偏好，并通过估值收缩利空高弹性半导体资产。","sectors":["存储芯片","人工智能硬件","半导体"],"tickers":[]}},{"id":"cb3e2039c4a81ac9","regions":["US"],"category":"宏观","importance":5,"title":"美欧科技争端升至关税威胁","summary":"美国拟调查欧盟对科技公司的监管处罚，并威胁以额外关税进行报复。","evidence":"原始标题：特朗普威胁对欧盟加征报复性关税；核验事实：【特朗普威胁对欧盟加征报复性关税】财联社7月25日电，美国总统特朗普24日称，美国政府将对欧盟启动贸易调查，并威胁要对欧盟加征关税，以报复欧盟对美国科技公司处以巨额罚款的做法。特朗普24日在社交媒体平台“真实社交”上发文，指责欧盟日前决定对谷歌公司罚款是在“抢掠”美国企业及美国纳税人。他警告，欧盟将为其行为付出“沉重”代价，“我们预计将尽快对其（欧盟）施加高额关税”。特朗普称，美方将立即依据《1974年贸易法》第301条对欧盟启动调查。该条款授权美国政府对其认定为对美国企业造成不公平负担的行为进行调查，并采取关税报复措施。欧盟委员会23日宣布，谷歌在网络搜索和应用商店业务中违反欧盟《数字市场法","source":"https://www.cls.cn/detail/2437027","sourceLabel":"财联社","publishedAt":"2026-07-25T12:29:03.000Z","ai":{"tone":"negative","interpretation":"贸易调查和关税威胁增加跨境合规与市场准入成本，利空谷歌及美欧科技和出口供应链估值。","sectors":["大型科技","出口链","贸易"],"tickers":["GOOGL"]}}],"translations":{"en":{"headline":"U.S. Equities Diverge as Chinese Stocks Retreat","summary":"Major U.S. equity indexes diverged while long-term rates rose, and both major Chinese indexes declined, weighing on overall risk appetite.","overview":{"interpretation":"Gains in the Dow and broad U.S. benchmark supported large-cap valuations, but a Nasdaq decline and higher long-term U.S. rates raised the risk-free rate and pressured growth valuations. Concurrent declines in major Chinese indexes weakened risk appetite and the equity financing environment.","positive":["U.S. large-cap value stocks","Broad U.S. large caps"],"negative":["U.S. growth stocks","Chinese large-cap stocks"]},"marketViews":{"CN":{"headline":"Major Chinese Indexes Retreat Together","summary":"Both major Chinese equity indexes declined, placing clear pressure on local equity risk appetite.","overview":{"interpretation":"Concurrent declines in both major indexes are negative for large-cap valuations and market risk appetite and may constrain the equity financing environment. Broad index heavyweight sectors faced pressure.","positive":[],"negative":["Chinese large-cap stocks","Index heavyweight sectors"]}},"US":{"headline":"U.S. Indexes Diverge as Rates Rise","summary":"The Dow and broad market benchmark advanced, the Nasdaq declined, and long-term rates moved higher.","overview":{"interpretation":"Gains in the Dow and broad market benchmark support large-cap value valuations and risk appetite. The Nasdaq decline and higher long-term rates raise the risk-free rate and pressure longer-duration growth valuations.","positive":["U.S. large-cap value stocks","Broad U.S. large caps"],"negative":["U.S. growth stocks","Long-duration assets"]}}},"stories":[{"title":"Services and Communications Consumption Outpace Goods Retail","summary":"Services retail grew faster than goods consumption in the first half, communications-equipment retail expanded quickly, and total retail sales posted modest growth.","interpretation":"Faster services and communications-equipment consumption benefits related revenue and cash flow. Slower total retail growth indicates weaker support for goods demand and pressures traditional retail, producing a mixed impact within consumer sectors.","sectors":["Services consumption","Communications equipment","Retail"]},{"title":"Producer-Goods Prices Create Divergent Supply-Chain Effects","summary":"More key producer-goods prices rose than fell; copper, aluminum, and several chemicals increased, while lithium iron phosphate declined sharply.","interpretation":"Higher copper, aluminum, and chemical prices improve upstream selling-price and revenue expectations but raise downstream purchasing costs. Lower lithium iron phosphate prices reduce material-producer revenue while lowering battery manufacturing costs, splitting profit effects across supply chains.","sectors":["Nonferrous metals","Chemicals","Battery materials"]},{"title":"U.S. Indexes Diverge Friday and Finish the Week Lower","summary":"The broad market and blue-chip indexes rose Friday while the Nasdaq fell; all three finished the week lower, and oil declined after a week of gains.","interpretation":"Gains in broad and blue-chip indexes support large-cap weights and daily risk appetite, but the Nasdaq decline and weekly losses pressure growth valuations. Lower oil reduces energy revenue expectations while easing costs for transportation and consumer industries.","sectors":["U.S. equities","Growth stocks","Energy"]},{"title":"Suzhou''s Electronics and Industrial Output Accelerate","summary":"Suzhou''s industrial output expanded, with stronger electronics, industrial-robot and integrated-circuit production.","interpretation":"Growth in electronics and robotics supports Yangtze River Delta equipment and chip orders, improving manufacturing cash-flow expectations through stronger industrial demand.","sectors":["Electronics","Industrial Robots","Semiconductors"]},{"title":"Treasury Yields Rise Sharply for the Week","summary":"Two-year and ten-year U.S. Treasury yields rose over the week, alongside higher real yields.","interpretation":"Higher nominal and real yields lift risk-free discount rates, pressuring high-valuation growth shares and other rate-sensitive assets.","sectors":["Growth Stocks","Real Estate","Utilities"]},{"title":"SEC Examines Preparations for Round-the-Clock Equity Trading","summary":"The SEC will discuss overnight operations, resilience and investor protection needed for 24-hour U.S. stock trading.","interpretation":"Longer trading hours can support exchange and brokerage revenue, while overnight liquidity and infrastructure needs raise operating costs and price-volatility risk.","sectors":["Exchanges","Brokerages","Financial Technology"]},{"title":"Industry Group Rebuts Claims of Concentrated Quant Selling","summary":"China''s private-fund industry committee said many quantitative funds were net buyers during the market decline rather than coordinated sellers.","interpretation":"Evidence of net buying reduces concern about quantitative-market mechanics and supports A-share risk appetite and brokerage trading, without directly changing corporate earnings.","sectors":["Quantitative Trading","Brokerages","A-Shares"]},{"title":"China Delivers Another Large Domestically Built LNG Carrier","summary":"China delivered its second domestically designed and built 180,000-cubic-meter LNG carrier.","interpretation":"Delivery validates high-end shipbuilding capability and converts backlog into revenue, supporting shipyards, cryogenic equipment and export-supply-chain cash flow.","sectors":["Shipbuilding","Cryogenic Equipment","Export Supply Chain"]},{"title":"U.S. Memory-Chip Supply Chain Pulls Back Sharply","summary":"The U.S. memory-chip and hardware-supply-chain index fell sharply on Friday while retaining a weekly gain.","interpretation":"The steep daily reversal hurts risk appetite for memory chips and AI hardware, pressuring high-beta semiconductor assets through valuation compression.","sectors":["Memory Chips","AI Hardware","Semiconductors"]},{"title":"U.S.-EU Technology Dispute Escalates to a Tariff Threat","summary":"The U.S. threatened a trade investigation and retaliatory tariffs over European penalties on technology companies.","interpretation":"Trade action raises cross-border compliance and market-access costs, pressuring Alphabet and transatlantic technology and export-supply-chain valuations.","sectors":["Big Tech","Export Supply Chain","Trade"]}]}},"isSample":false}',
